<?php
// Read-only projections. Stock posting remains in the existing Outflow workflows.
function gm_platform($input){$p=$input['platform']??'Shopee';return in_array($p,['Shopee','Lazada','TikTok','Manual'],true)?$p:'Shopee';}
function gm_products(){static $all=null;if($all===null){$all=[];foreach(db()->query('SELECT id,master_sku,name FROM products') as $p)$all[(int)$p['id']]=$p;}return $all;}
function gm_items_text($items){$p=gm_products();$s=[];foreach($items as $id=>$qty)$s[]=($p[$id]['master_sku']??'#'.$id).' · '.($p[$id]['name']??'Product').' × '.$qty;return implode('; ',$s);}
function gm_order_items(){static $result=null;if($result!==null)return $result;$result=[];foreach(db()->query('SELECT order_id,source_json,components_json FROM om_lines ORDER BY id') as $l){$s=json_decode($l['source_json'],true)?:[];foreach(json_decode($l['components_json'],true)?:[] as $c){$id=(int)($c['product_id']??0);if($id)$result[$l['order_id']][$id]=($result[$l['order_id']][$id]??0)+(int)($s['qty']??1)*(int)($c['per_bundle']??1);}}foreach(db()->query('SELECT l.order_id,o.product_id,SUM(o.qty) qty FROM om_postings l JOIN outflows o ON o.id=l.outflow_id WHERE o.qty>0 GROUP BY l.order_id,o.product_id') as $r)if(!isset($result[$r['order_id']][$r['product_id']]))$result[$r['order_id']][$r['product_id']]=(int)$r['qty'];return $result;}
function gm_ledger_groups(){static $groups=null;if($groups!==null)return $groups;$groups=[];foreach(db()->query("SELECT o.*,p.master_sku,p.name product_name,u.name actor FROM outflows o LEFT JOIN products p ON p.id=o.product_id LEFT JOIN users u ON u.id=o.user_id WHERE o.qty>0 ORDER BY o.id") as $r){$batch=(int)$r['import_batch_id'];if($batch>0)$key='batch:'.$batch;else{if(!in_array($r['type'],['Warranty Replacement','Sponsorship','Marketing','Freebie','Internal Use','Transfer Out','Supplier Return','Direct Sale'],true)&&!($r['type']==='Order'&&in_array($r['platform'],['Internal','Direct'],true)))continue;$key='legacy:'.hash('sha256',json_encode([$r['txn_date'],$r['order_id'],$r['type'],$r['user_id']]));}$groups[$key][]=$r;}return $groups;}
function gm_release_effect($lines){$original=0;$active=0;foreach($lines as $r){$original+=(int)$r['qty'];if(empty($r['reversed_by_request']))$active+=(int)$r['qty'];}return [$original,$active];}
function gm_manual_records(){static $records=null;if($records!==null)return $records;$records=[];$groups=gm_ledger_groups();foreach(db()->query("SELECT b.*,u.name preparer FROM import_batches b LEFT JOIN users u ON u.id=b.user_id WHERE b.import_type='Manual Outflow' ORDER BY b.id DESC") as $b){$w=json_decode($b['result_json']??'{}',true)['workflow']??[];$d=$w['data']??[];$lines=$groups['batch:'.$b['id']]??[];$items=[];foreach($d['items']??[] as $i)$items[(int)$i['product_id']]=($items[(int)$i['product_id']]??0)+(int)$i['qty'];if(!$items)foreach($lines as $l)$items[$l['product_id']]=($items[$l['product_id']]??0)+(int)$l['qty'];[$original,$active]=gm_release_effect($lines);$status=$original?($active===0?'Reversed':($active<$original?'Partially Reversed':'Posted')):(['Review'=>'Awaiting Confirmation','Complete'=>'Posted','Confirmed'=>'Posted','Successful'=>'Posted'][$b['status']]??$b['status']);$records[]=['id'=>(int)$b['id'],'kind'=>'batch','date'=>$d['txn_date']??substr($b['created_at'],0,10),'time'=>$b['created_at'],'ref'=>$d['ref']??$b['filename'],'purpose'=>$d['type']??'Manual Outflow','recipient'=>$d['recipient']??'Not recorded','qty'=>array_sum($items),'items'=>$items,'posting'=>$status,'effect'=>-$active,'actor'=>$w['posted_by']['name']??$b['preparer'],'owner_id'=>$b['user_id'],'attachment'=>!empty($b['stored_path']),'workflow'=>$w,'lines'=>$lines];}
 foreach($groups as $key=>$lines){if(!str_starts_with($key,'legacy:'))continue;$r=$lines[0];[$original,$active]=gm_release_effect($lines);$items=[];foreach($lines as $l)$items[$l['product_id']]=($items[$l['product_id']]??0)+(int)$l['qty'];$records[]=['id'=>(int)$r['id'],'kind'=>'legacy','date'=>$r['txn_date'],'time'=>$r['created_at'],'ref'=>$r['order_id']?:'OUT-'.$r['id'],'purpose'=>$r['type']==='Order'?'Direct Sale':$r['type'],'recipient'=>'See original transaction','qty'=>$original,'items'=>$items,'posting'=>$active===0?'Reversed':($active<$original?'Partially Reversed':'Posted'),'effect'=>-$active,'actor'=>$r['actor'],'owner_id'=>$r['user_id'],'attachment'=>false,'workflow'=>[],'lines'=>$lines];}return $records;}
function gm_records($input){$manual=gm_platform($input)==='Manual';if($manual)$rows=gm_manual_records();else{$filter=$input;unset($filter['q']);$filter['platform']=gm_platform($input);$rows=om_filtered_orders($filter);$items=gm_order_items();$reserved=[];foreach(db()->query('SELECT order_id,SUM(qty) qty FROM om_reservations GROUP BY order_id') as $r)$reserved[$r['order_id']]=(int)$r['qty'];foreach($rows as &$r){$r['date']=$r['fulfillment_date'];$r['time']=$r['created_at'];$r['ref']=$r['order_no'];$r['items']=$items[$r['id']]??[];$r['qty']=array_sum($r['items']);$r['reserved']=$reserved[$r['id']]??0;}unset($r);}
 $q=mb_strtolower(trim($input['q']??''));$rows=array_values(array_filter($rows,function($r)use($input,$q,$manual){if($q!==''&&!str_contains(mb_strtolower($r['ref'].' '.gm_items_text($r['items']).' '.($r['recipient']??'').' '.($r['purpose']??'')),$q))return false;if(!$manual){if(($input['attention']??'')==='open'){$age=(strtotime(date('Y-m-d'))-strtotime($r['date']))/86400;return (bool)($r['exception_text']||$r['monitoring']==='Missing'||($r['monitoring']!=='Resolved'&&$age>=om_alert_settings()['high_days']));}return true;}if(!empty($input['from'])&&$r['date']<report_date($input['from']))return false;if(!empty($input['to'])&&$r['date']>report_date($input['to']))return false;if(!empty($input['posting'])&&$r['posting']!==$input['posting'])return false;if(!empty($input['owner_id'])&&(int)$r['owner_id']!==(int)$input['owner_id'])return false;if(($input['report_view']??'')==='open'&&!in_array($r['posting'],['Awaiting Confirmation','Partially Reversed'],true))return false;return true;}));$direction=($input['sort']??'newest')==='oldest'?1:-1;usort($rows,fn($a,$b)=>$direction*(strcmp($a['date'],$b['date'])?:strcmp($a['time'],$b['time'])?:($a['id']<=>$b['id'])));return $rows;}
function gm_report($input){$manual=gm_platform($input)==='Manual';$heads=$manual?['Transaction Date','Reference / DR','Purpose','Recipient / Business Unit','Products / Quantities','Total Quantity','Posting Status','Net Physical Stock Effect','Processed By']:['Fulfillment Date','Platform','Shop','Order ID','Products / Quantities','Product Units','Platform Status','Inventory Posting','Monitoring','Reserved Units','Last Checked','Responsible User','Exception'];$rows=[];foreach(gm_records($input) as $r)$rows[]=$manual?[$r['date'],(string)$r['ref'],$r['purpose'],$r['recipient'],gm_items_text($r['items']),$r['qty'],$r['posting'],$r['effect'],$r['actor']]:[$r['date'],$r['platform'],$r['shop'],(string)$r['ref'],gm_items_text($r['items']),$r['qty'],$r['platform_status'],$r['posting'],$r['monitoring'],$r['reserved'],$r['last_seen_at']??'Never checked',$r['owner_name'],$r['exception_text']];return ['title'=>$manual?'Manual Outflow Monitoring':gm_platform($input).' Order Monitoring','headers'=>$heads,'rows'=>$rows,'filters'=>$input,'summary'=>[],'links'=>[],'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name'],'notes'=>['All matching records are exported. Monitoring does not post stock. Net physical effect excludes reversed releases.']];}
